# Simple end-to-end AI pipeline

def preprocess(text):
    return text.lower().split()

def extract_features(tokens):
    positive_words = {"good", "great", "excellent", "amazing"}
    return sum(1 for t in tokens if t in positive_words)

def predict(sentiment_score):
    return "Positive" if sentiment_score >= 1 else "Negative"

# Test the pipeline
reviews = [
    "This product is amazing and great",
    "Terrible experience, very bad",
]

for review in reviews:
    tokens = preprocess(review)
    score = extract_features(tokens)
    result = predict(score)
    print(f"Review: {review}")
    print(f"Sentiment: {result}\n")
